/**
 * @jest-environment node
 */
import { resolve } from 'path';

import sharp from 'sharp';

// Raster icons are generated by scripts/generate-pwa-icons.mjs and committed.
const iconsDir = resolve(__dirname, '../../public/icons');

describe('generated PNG icons', () => {
  it.each([
    ['icon-192.png', 192],
    ['icon-512.png', 512],
    ['icon-maskable-192.png', 192],
    ['icon-maskable-512.png', 512],
    ['apple-touch-icon.png', 180],
  ])('should ship %s as a %ipx square PNG', async (filename, size) => {
    const { format, width, height } = await sharp(resolve(iconsDir, filename)).metadata();
    expect(format).toBe('png');
    expect(width).toBe(size);
    expect(height).toBe(size);
  });

  it.each(['icon-maskable-192.png', 'icon-maskable-512.png', 'apple-touch-icon.png'])(
    'should ship %s fully opaque (no alpha channel)',
    async (filename) => {
      const { hasAlpha } = await sharp(resolve(iconsDir, filename)).metadata();
      expect(hasAlpha).toBe(false);
    },
  );
});
